package com.argument.teachingtrial;
import com.argument.common.response.ApiResponse;
import com.argument.adjudication.AdjudicationController;
import com.argument.version.port.VersionIdentity;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.context.annotation.Profile;
import org.springframework.web.bind.annotation.*;
/** Trial endpoints only. ED01-ED20 remain pending; no generated READY SDK is modified. */
@RestController @Profile("(local | test) & !prod") @RequestMapping("/api/local/member-d/teaching")
public class TeachingTrialController {
 private final TeachingWorkspaceService service;private final TeachingAnswerService answers;private final VersionIdentity identity;
 public TeachingTrialController(TeachingWorkspaceService service,TeachingAnswerService answers,VersionIdentity identity){this.service=service;this.answers=answers;this.identity=identity;}
 @GetMapping("/workspace") public ApiResponse<ObjectNode> workspace(@RequestHeader(value="Authorization",required=false)String auth){return ApiResponse.ok(service.overview(identity.authenticate(auth)));}
 @PostMapping("/courses") public ApiResponse<ObjectNode> course(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(service.createCourse(identity.authenticate(auth),key,body));}
 @PostMapping("/courses/{id}/activate") public ApiResponse<ObjectNode> activate(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.activateCourse(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/members/{id}/deactivate") public ApiResponse<ObjectNode> member(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.deactivateMember(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/source-grants") public ApiResponse<ObjectNode> grant(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(service.grantSource(identity.authenticate(auth),key,body));}
 @PostMapping("/source-grants/{id}/revoke") public ApiResponse<ObjectNode> revoke(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.revokeSource(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/standards") public ApiResponse<ObjectNode> standard(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(service.createStandard(identity.authenticate(auth),key,body));}
 @GetMapping("/standards/{id}") public ApiResponse<ObjectNode> standardRead(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id){return ApiResponse.ok(service.standard(identity.authenticate(auth),id));}
 @PostMapping("/standards/{id}/publish") public ApiResponse<ObjectNode> standardPublish(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.publishStandard(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/standards/{id}/revisions") public ApiResponse<ObjectNode> revise(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(service.reviseStandard(identity.authenticate(auth),id,key,body));}
 @PostMapping("/assignments") public ApiResponse<ObjectNode> assignment(@RequestHeader(value="Authorization",required=false)String auth,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(service.createAssignment(identity.authenticate(auth),key,body));}
 @PatchMapping("/assignments/{id}") public ApiResponse<ObjectNode> update(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.updateAssignment(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/assignments/{id}/publish") public ApiResponse<ObjectNode> publish(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(service.publishAssignment(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @GetMapping("/assignments/{id}/context") public ApiResponse<ObjectNode> context(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id){return ApiResponse.ok(answers.studentContext(identity.authenticate(auth),id));}
 @PostMapping("/assignments/{id}/attempts") public ApiResponse<ObjectNode> attempt(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(answers.createAttempt(identity.authenticate(auth),id,key,body));}
 @PatchMapping("/answers/{id}") public ApiResponse<ObjectNode> save(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(answers.save(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @PostMapping("/answers/{id}/submit") public ApiResponse<ObjectNode> submit(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestHeader(value="If-Match",required=false)String match,@RequestBody ObjectNode body){return ApiResponse.ok(answers.submit(identity.authenticate(auth),id,key,AdjudicationController.integer(match),body));}
 @GetMapping("/results") public ApiResponse<ObjectNode> results(@RequestHeader(value="Authorization",required=false)String auth){return ApiResponse.ok(answers.results(identity.authenticate(auth)));}
 @GetMapping("/results/{id}") public ApiResponse<ObjectNode> result(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id){return ApiResponse.ok(answers.result(identity.authenticate(auth),id));}
 @PostMapping("/results/{id}/feedback") public ApiResponse<ObjectNode> feedback(@RequestHeader(value="Authorization",required=false)String auth,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody ObjectNode body){return ApiResponse.ok(answers.feedback(identity.authenticate(auth),id,key,body));}
}
